// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address sender, address target) public {
        vm.assume(sender != address(0));
        vm.assume(target != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        vm.assume(sender != c.owner());
        vm.deal(address(c), amount);
        vm.deal(sender, 1 ether);
        bool ok;
        vm.prank(sender);
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
